package org.apache.commons.compress.compressors.bzip2;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.DeflaterOutputStream;
import org.apache.commons.compress.compressors.CompressorInputStream;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BZip2CompressorInputStream_BZip2CompressorInputStream_TriageGen2Test {

    /**
     * Test the constructor with a valid BZip2 stream and decompressConcatenated = false.
     */
    @Test
    public void testConstructorValidStream() throws IOException {
        byte[] data = "Hello BZip2 World!".getBytes(StandardCharsets.UTF_8);
        byte[] compressedData = createBZip2Data(data);

        try (InputStream bis = new ByteArrayInputStream(compressedData);
             BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(bis, false)) {

            byte[] result = bzIn.readAllBytes();
            Assert.assertArrayEquals(data, result);
        }
    }

    /**
     * Test the constructor with a valid BZip2 stream and decompressConcatenated = true.
     * This tests the logic path for concatenated streams.
     */
    @Test
    public void testConstructorConcatenatedStream() throws IOException {
        byte[] data1 = "First Part ".getBytes(StandardCharsets.UTF_8);
        byte[] data2 = "Second Part".getBytes(StandardCharsets.UTF_8);

        // Manually concatenate two bzip2 streams
        byte[] comp1 = createBZip2Data(data1);
        byte[] comp2 = createBZip2Data(data2);
        byte[] concatenated = new byte[comp1.length + comp2.length];
        System.arraycopy(comp1, 0, concatenated, 0, comp1.length);
        System.arraycopy(comp2, 0, concatenated, comp1.length, comp2.length);

        try (InputStream bis = new ByteArrayInputStream(concatenated);
             BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(bis, true)) {

            byte[] result = bzIn.readAllBytes();
            byte[] expected = new byte[data1.length + data2.length];
            System.arraycopy(data1, 0, expected, 0, data1.length);
            System.arraycopy(data2, 0, expected, data1.length, data2.length);

            Assert.assertArrayEquals(expected, result);
        }
    }

    /**
     * Test the constructor with invalid BZip2 data to trigger IOException during initBlock/setupBlock.
     */
    @Test(expected = IOException.class)
    public void testConstructorInvalidData() throws IOException {
        byte[] invalidData = new byte[]{0x01, 0x02, 0x03, 0x04};
        try (InputStream bis = new ByteArrayInputStream(invalidData);
             BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(bis)) {
            bzIn.read();
        }
    }

    /**
     * Test the constructor with a null InputStream.
     */
    @Test(expected = NullPointerException.class)
    public void testConstructorNullInputStream() throws IOException {
        new BZip2CompressorInputStream(null);
    }

    /**
     * Test the matches static method.
     */
    @Test
    public void testMatches() {
        // BZip2 signature: BZh
        byte[] signature = {'B', 'Z', 'h'};
        byte[] validData = {'B', 'Z', 'h', 0x01, 0x02};
        byte[] invalidData = {'A', 'B', 'C', 'D'};

        Assert.assertTrue(BZip2CompressorInputStream.matches(validData, 3));
        Assert.assertFalse(BZip2CompressorInputStream.matches(invalidData, 3));
        Assert.assertFalse(BZip2CompressorInputStream.matches(validData, 2));
    }

    /**
     * Helper method to create a valid BZip2 compressed byte array.
     * Since Apache Commons Compress doesn't provide a simple BZip2OutputStream in all versions 
     * without extra dependencies, we simulate the stream or use a known pattern.
     * For the sake of this unit test, we assume the environment can produce BZip2.
     * Note: In a real professional environment, one would use BZip2CompressorOutputStream.
     */
    private byte[] createBZip2Data(byte[] data) throws IOException {
        // Using a real BZip2 compressor from the same library to ensure validity
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream bzOut = 
                new org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream(baos)) {
            bzOut.write(data);
        }
        return baos.toByteArray();
    }
}
